import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def transform(grid):
    s = grid[0].index(2); w = len(grid[0]); n = min(s, w-1-s); h = w
    out = [[0]*w for _ in range(h)]
    for r in range(n+1):
        out[r][s-r] = 2; out[r][s+r] = 2
    k = 0
    while True:
        r0 = 3+2*k; d = s-4-4*k
        drew = False
        for r in range(r0, h):
            c = r + d
            if 0 <= c < w: out[r][c] = 1; drew = True
            if c >= w: break
        if not drew and r0 > h: break
        k += 1
    return out
for name in ['Demo pair 1','Demo pair 2']:
    print(name, transform(G[name+' input'])==G[name+' output'])
out=transform(G['Test input'])
for r in out: print(''.join(str(v) for v in r))
